// Build search index from imported data
const searchIndex = [];
for (const { book, name, chapter, data } of chapters) {
  const verseNums = Object.keys(data)
    .map(n => parseInt(n, 10))
    .filter(n => !isNaN(n))
    .sort((a, b) => a - b);

  for (const v of verseNums) {
    if (data[v]?.en) {
      searchIndex.push({
        book,
        bookName: name,
        chapter,
        verse: v,
        en: data[v].en,
      });
    }
  }
}

export { searchIndex };
